20e32aebea510fb3626c5fb9ed03aaca:
query BaseApplicationQuery(
  $faceId: ID
  $folderId: ID
) {
  folders(faceId: $faceId) {
    nodes {
      id
      name
      photoCount
    }
  }
  faces(folderId: $folderId) {
    ...FaceFragment_faces
  }
}

fragment FaceFragment_face on Face {
  id
  thumbnailUrl
  photoCount
}

fragment FaceFragment_faces on FaceConnection {
  nodes {
    id
    ...FaceFragment_face
  }
}

